	private static void seed(SailRepository repository) {
		try (var connection = repository.getConnection()) {
			connection.begin();
			for (Value object : OBJECTS) {
				connection.add(SUBJECT, PREDICATE, object);
			}
			connection.commit();
		}
	}

	private static List<Value> readMemoryObjects(SailRepository repository) {
		List<Value> objects = new ArrayList<>();
		try (var connection = repository.getConnection();
				var statements = connection.getStatements(SUBJECT, PREDICATE, null, false)) {
			while (statements.hasNext()) {
				objects.add(statements.next().getObject());
			}
		}
		return objects;
	}

	private static Map<Value, Long> frequencies(List<Value> values) {
		Map<Value, Long> result = new HashMap<>();
		for (Value value : values) {
			result.merge(value, 1L, Math::addExact);
		}
		return result;
	}
